from datetime import date, timedelta
from collections import defaultdict


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Maps employee -> year -> used_days
        self._used: dict[str, dict[int, int]] = defaultdict(lambda: defaultdict(int))

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if start > end:
            raise ValueError("Start date must be before or equal to end date.")

        # Requirement 2: Request made less than 3 days before start date is rejected
        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days in advance.")

        # Group requested leave days by year
        current = start
        days_by_year: dict[int, int] = defaultdict(int)

        while current <= end:
            # Requirement 4: Weekends (5: Saturday, 6: Sunday) and holidays do not use leave days
            if current.weekday() < 5 and current not in self.holidays:
                days_by_year[current.year] += 1
            current += timedelta(days=1)

        # Requirement 1 & 3: Check remaining days per year (no carry-over)
        for yr, needed in days_by_year.items():
            if self.remaining(employee, yr) < needed:
                raise ValueError(
                    f"Employee '{employee}' does not have enough remaining leave days for year {yr}."
                )

        # Deduct days
        total_used = 0
        for yr, needed in days_by_year.items():
            self._used[employee][yr] += needed
            total_used += needed

        return total_used

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self._used[employee][year]
```

